package net.civeira.phylax.feature.access.userverificationcode.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userverificationcode.domain.UserVerificationCode;
import net.civeira.phylax.feature.access.userverificationcode.domain.valueobject.ReturnUrlVO;

class ReturnUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of return url of user verification code")
  void test_return_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    ReturnUrlValueHolder<Object> value = new ReturnUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.returnUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getReturnUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getReturnUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.returnUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getReturnUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getReturnUrl().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of return url of user verification code")
  void test_return_url_value_holder_assign_value_object() {
    Object holder = new Object();
    ReturnUrlValueHolder<Object> value = new ReturnUrlValueHolder<>(holder);
    ReturnUrlVO vo = ReturnUrlVO.from("one");
    Assertions.assertFalse(value.getReturnUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.returnUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getReturnUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.returnUrl(Optional.empty()));
    Assertions.assertFalse(value.getReturnUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.returnUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getReturnUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of return url of user verification code against the original")
  void test_return_url_value_holder_read() {
    Object holder = new Object();
    ReturnUrlValueHolder<Object> value = new ReturnUrlValueHolder<>(holder);
    ReturnUrlVO vo = ReturnUrlVO.from("one");
    ReturnUrlVO other = ReturnUrlVO.from("one");
    UserVerificationCode original = Mockito.mock(UserVerificationCode.class);
    Mockito.when(original.getReturnUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readReturnUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readReturnUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.returnUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readReturnUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readReturnUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of return url of user verification code")
  void test_return_url_value_holder_unset() {
    Object holder = new Object();
    ReturnUrlValueHolder<Object> value = new ReturnUrlValueHolder<>(holder);
    ReturnUrlVO vo = ReturnUrlVO.from("one");
    value.returnUrl(vo);
    Assertions.assertSame(holder, value.unsetReturnUrlIfMatches("returnUrl_other"));
    Assertions.assertTrue(value.getReturnUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetReturnUrlIfMatches("returnUrl"));
    Assertions.assertFalse(value.getReturnUrlValue().isPresent(),
        "The field name must clear the value");
    value.returnUrl(vo);
    Assertions.assertSame(holder, value.unsetReturnUrl());
    Assertions.assertFalse(value.getReturnUrlValue().isPresent(), "Unset must clear the value");
  }
}
